import{_ as e,o as t,c as r,a2 as s}from"./chunks/framework.BWuWLRhz.js";const h=JSON.parse('{"title":"索引","description":"","frontmatter":{},"headers":[],"relativePath":"zh-CN/user-guide/settings/index-drives.md","filePath":"zh-CN/user-guide/settings/index-drives.md","lastUpdated":1783414071000}'),n={name:"zh-CN/user-guide/settings/index-drives.md"};function i(a,o,l,d,g,c){return t(),r("div",null,[...o[0]||(o[0]=[s('<h1 id="索引" tabindex="-1">索引 <a class="header-anchor" href="#索引" aria-label="Permalink to &quot;索引&quot;">​</a></h1><p>三个 Tab:<strong>本地驱动器</strong>、<strong>网络驱动器</strong>、<strong>排除规则</strong>。</p><h2 id="本地驱动器" tabindex="-1">本地驱动器 <a class="header-anchor" href="#本地驱动器" aria-label="Permalink to &quot;本地驱动器&quot;">​</a></h2><ul><li>顶部状态卡片汇总已索引的驱动器数量与项目数量，并提供<strong>重建索引</strong>按钮做全量重扫描。</li><li>每个本地驱动器一行:<strong>启用/禁用复选框</strong>、驱动器名称、文件系统(NTFS/ReFS 等)、当前状态、已索引 项目数，以及每行独立的<strong>重建</strong>/<strong>移除</strong>操作。</li><li>本地驱动器通过 Windows USN 日志持续实时更新——手动重建很少需要，但如果发现内容不同步，随时可 以用它。</li></ul><h2 id="网络驱动器" tabindex="-1">网络驱动器 <a class="header-anchor" href="#网络驱动器" aria-label="Permalink to &quot;网络驱动器&quot;">​</a></h2><ul><li>与本地驱动器相同的状态卡片和<strong>重建索引</strong>按钮。</li><li>每个已映射的网络驱动器一行:启用复选框、路径/名称、状态(索引中 / 就绪 / 已缓存 / 失败 / 等待中 / 已连接)、项目数，以及<strong>刷新模式</strong>下拉框: <ul><li><strong>手动</strong> —— 只在手动触发(重建索引)时刷新。</li><li><strong>每 15 分钟</strong></li><li><strong>每小时</strong></li><li><strong>每天</strong></li></ul></li><li>如果检测到安装了 Windows Subsystem for Linux，会自动出现一个 <strong>WSL 发行版</strong> 子区域，每个发行 版都有和网络驱动器一样的启用/状态/刷新模式控件。</li></ul><p>网络共享没有本地 NTFS 卷那样的变更日志可供监听，所以采用定时刷新而不是实时更新。</p><h2 id="排除规则" tabindex="-1">排除规则 <a class="header-anchor" href="#排除规则" aria-label="Permalink to &quot;排除规则&quot;">​</a></h2><p>三个子 Tab，形态完全一致:一个单条输入框 + <strong>添加</strong>按钮，一个可编辑/删除每一条规则的列表，以及一 个批量多行文本框，配 <strong>从列表生成</strong> / <strong>应用到列表</strong> 两个按钮，用来一次性编辑全部规则。</p><ul><li><strong>路径排除</strong> —— 完整路径或环境变量(例如 <code>D:\\Cache</code>、<code>%ProgramData%</code>)。</li><li><strong>Glob 通配符</strong> —— <code>*</code>(文件名中任意字符)、<code>?</code>(单个字符)、<code>**</code>(递归目录)。示例:<code>*.tmp</code>、 <code>**/node_modules/**</code>、<code>bin/**</code>。</li><li><strong>正则表达式</strong> —— 针对路径/文件名做部分匹配的任意正则。示例:<code>^\\.</code>(隐藏文件)、<code>~$</code>(Office 临时文件)、<code>\\.git\\</code>。</li></ul><p>排除规则对本地和网络索引都生效，应用排除规则的改动后，网络驱动器会自动重新扫描。</p>',11)])])}const _=e(n,[["render",i]]);export{h as __pageData,_ as default};
